import{_ as t,o as d,c as o,a2 as r}from"./chunks/framework.CFuv5BrO.js";const b=JSON.parse('{"title":"浏览器自动化","description":"独立 Chrome profile、页面快照、动作审批、证据和完成断言。","frontmatter":{"title":"浏览器自动化","description":"独立 Chrome profile、页面快照、动作审批、证据和完成断言。","outline":[2,3]},"headers":[],"relativePath":"design/browser.md","filePath":"design/browser.md","lastUpdated":1795426969000}'),a={name:"design/browser.md"};function i(l,e,c,s,h,n){return d(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="浏览器自动化" tabindex="-1">浏览器自动化 <a class="header-anchor" href="#浏览器自动化" aria-label="Permalink to &quot;浏览器自动化&quot;">​</a></h1><p>Hearth 的浏览器能力目标是“能替你办事，同时能核对”。它不把模型直接接到一个看不见的浏览器上，而是把页面压成可审阅的元素清单，把每个高风险动作变成可审批、可回放、可断言的动作。</p><h2 id="运行方式" tabindex="-1">运行方式 <a class="header-anchor" href="#运行方式" aria-label="Permalink to &quot;运行方式&quot;">​</a></h2><ul><li>使用独立 Chrome profile，路径在 <code>.hearth/browser/profile</code>，不与用户默认 Chrome 共享 cookie。</li><li>启动时优先使用系统 Chrome，其次 Edge/Chromium；<code>HEARTH_BROWSER</code> 可指向可执行文件。</li><li>每个任务一个标签页上下文，最多 4 个任务同时打开，最多 6 个标签页；空闲 10 分钟释放。</li><li>Chrome 136+ 不允许在默认 profile 上开启远程调试，因此没有“直接接管默认 profile”的捷径。</li></ul><h2 id="页面快照" tabindex="-1">页面快照 <a class="header-anchor" href="#页面快照" aria-label="Permalink to &quot;页面快照&quot;">​</a></h2><p>每次读取页面都会：</p><ul><li>给可交互元素写稳定 <code>data-hearth-ref</code>（<code>e1</code>、<code>e2</code>…）；</li><li>返回 role、name、value、disabled、checked、bbox、tag、type；</li><li>密码字段不返回值；</li><li>正文截断到 2400 字，页面摘要上限 12k；</li><li>生成页面 digest，作为动作前后的比较依据。</li></ul><p>模型只能按稳定 ID 操作，不直接写 CSS 选择器，也不接触 cookie、密码或浏览器存储。</p><h2 id="_13-个工具" tabindex="-1">13 个工具 <a class="header-anchor" href="#_13-个工具" aria-label="Permalink to &quot;13 个工具&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>用途</th><th>默认风险</th></tr></thead><tbody><tr><td><code>browser_open</code></td><td>打开 http/https；新域名需审批</td><td>中</td></tr><tr><td><code>browser_read</code></td><td>读页面文本与元素清单</td><td>低</td></tr><tr><td><code>browser_click</code></td><td>点击普通元素；提交/支付/删除类元素拒绝</td><td>中</td></tr><tr><td><code>browser_type</code></td><td>输入文本；密码字段拒绝</td><td>中</td></tr><tr><td><code>browser_key</code></td><td>按键，如 Enter、Escape</td><td>中</td></tr><tr><td><code>browser_wait</code></td><td>等元素、文本或网络空闲</td><td>低</td></tr><tr><td><code>browser_submit</code></td><td>提交表单；每次单独审批</td><td>高</td></tr><tr><td><code>browser_tabs</code></td><td>列出、新建、切换、关闭标签页</td><td>中</td></tr><tr><td><code>browser_screenshot</code></td><td>截图到任务输出目录</td><td>低</td></tr><tr><td><code>browser_upload</code></td><td>上传工作区内文件</td><td>高</td></tr><tr><td><code>browser_download</code></td><td>下载到任务输出目录</td><td>高</td></tr><tr><td><code>browser_assert</code></td><td>断言文本、URL、元素存在/不存在</td><td>低</td></tr><tr><td><code>browser_recipe</code></td><td>列出/保存/回放/删除站点配方</td><td>中</td></tr></tbody></table><p>危险按钮识别覆盖 <code>submit</code>、<code>pay</code>、<code>delete</code>、<code>send</code>、<code>提交</code>、<code>发送</code>、<code>支付</code>、<code>删除</code>、<code>确认</code>、<code>下单</code> 等中英文标签。调用过浏览器工具的任务，<code>finish_task</code> 前必须至少有一条通过的断言，且最后一条断言必须通过。</p><h2 id="审批与授权" tabindex="-1">审批与授权 <a class="header-anchor" href="#审批与授权" aria-label="Permalink to &quot;审批与授权&quot;">​</a></h2><ul><li><code>browser_open</code> 首次访问新域名进入审批；选择“该域名始终允许”会写入一条 30 天、无次数上限的域名授权。</li><li>提交、上传、下载每次审批；高风险站点（银行、支付、邮箱、政府站点）不能被“始终允许”绕过。</li><li>只允许 http/https；<code>file://</code>、<code>javascript:</code> 等协议拒绝。</li><li>站点配方保存的是步骤和断言，不保存 cookie、密码或页面正文。</li></ul><h2 id="证据" tabindex="-1">证据 <a class="header-anchor" href="#证据" aria-label="Permalink to &quot;证据&quot;">​</a></h2><p>每次动作保存：</p><ul><li>动作前后截图：<code>&lt;BROWSER_EVIDENCE_DIR&gt;/&lt;task&gt;/&lt;timestamp&gt;-before.png</code> / <code>-after.png</code>；</li><li><code>evidence.json</code>：URL、标题、页面 digest、动作 digest、时间；</li><li>证据保存在任务工作区；对话运行卡显示动作摘要，完整截图与证据列表可在任务产物和日志中查看。</li></ul><p>证据默认保留 7 天，每任务最多 500 个文件；清理任务会删除超期文件，不删除任务产物。</p><h2 id="完成判定" tabindex="-1">完成判定 <a class="header-anchor" href="#完成判定" aria-label="Permalink to &quot;完成判定&quot;">​</a></h2><p>浏览器任务不能只靠“模型说完成了”。完成前必须：</p><ol><li>至少一条 <code>browser_assert</code> 通过；</li><li>最后一条断言通过；</li><li>失败断言或未断言会阻止 <code>finish_task</code>。</li></ol><p>这让“页面真的到了成功页”成为完成证据，而不是模型的自述。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><ul><li>不读取 cookie、密码、浏览器历史或支付信息。</li><li>不承诺绕过验证码、风控或网站条款。</li><li>不实现“直接控制默认 Chrome”的扩展桥；需要登录的站点请在独立 profile 中登录一次。</li><li>上传只允许任务工作区内的文件；下载落到任务输出目录，不自动打开。</li></ul>',23)])])}const _=t(a,[["render",i]]);export{b as __pageData,_ as default};
